'use strict';

// Suporte a PWA: permite "Instalar" o Golden SaaS como app (janela própria,
// ícone, atalho na área de trabalho e menu Iniciar). Os ícones ficam embutidos
// em base64 pra não depender de caminho de arquivo em disco.

const ICON_192 = Buffer.from('', 'base64');
const ICON_512 = Buffer.from('', 'base64');

const MANIFEST = JSON.stringify({
  name: 'Golden SaaS',
  short_name: 'Golden SaaS',
  description: 'Sistema de gestão da Golden Motors',
  start_url: '/',
  scope: '/',
  display: 'standalone',
  orientation: 'portrait-primary',
  background_color: '#111111',
  theme_color: '#111111',
  icons: [
    { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ],
});

// Service worker mínimo: só existe para o navegador considerar o app
// "instalável". NÃO faz cache (o sistema é renderizado no servidor e usa
// sessão — cache quebraria login/dados). Repassa tudo para a rede.
const SERVICE_WORKER = `
self.addEventListener('install', function (e) { self.skipWaiting(); });
self.addEventListener('activate', function (e) { self.clients.claim(); });
self.addEventListener('fetch', function (e) { /* passthrough: sem cache */ });
`;

module.exports = { ICON_192, ICON_512, MANIFEST, SERVICE_WORKER };
